export default function UserOrders({ orders = [] }) {
  if (orders.length === 0) {
    return <p>No orders placed yet.</p>;
  }

  return (
    <div>
      <h3>Your Orders</h3>
      {orders.map(o => (
        <div key={o.order_id}>
          <h4>Order #{o.order_id}</h4>
          <p>Status: {o.status}</p>
          <p>Total: ₹{o.total}</p>

          <ul>
            {o.items.map((i, idx) => (
              <li key={idx}>{i.name} × {i.quantity}</li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
}
